const m = $json;
const from = Array.isArray(m.from?.value) ? m.from.value[0] : null;
const senderEmail = from?.address || m.from?.text?.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0] || m.senderEmail;
const rawHeaders = m.headers || m.payload?.headers || [];
const headers = Array.isArray(rawHeaders) ? rawHeaders : Object.entries(rawHeaders).map(([name, value]) => ({ name, value }));
const rawAttachments = Array.isArray(m.attachments) ? m.attachments : Object.values(m.attachments || {});
return [{ json: { messageId: String(m.id || m.messageId || ''), threadId: String(m.threadId || ''), senderEmail, sender: from?.name || senderEmail, subject: String(m.subject || ''), bodyText: String(m.textPlain || m.text || m.snippet || ''), receivedAt: m.internalDate ? new Date(Number(m.internalDate)).toISOString() : new Date().toISOString(), headers: headers.map(h => ({ name: h.name || h.key, value: h.value || h.valueText || '' })), attachments: rawAttachments.map(a => ({ filename: a.fileName || a.filename, mimeType: a.mimeType, size: a.fileSize || a.size })) } }];
